schemas.schema-01-systematic.prisma:
/// Top-level taxonomy for discussion boards. Defines unique, human-visible
/// categories that organize and classify all board content. Referenced by
/// {@link pol_eco_board_boards} for structural organization. Immutable
/// except for changes to name, description, or display order. Board and user
/// content models reference this category but do not own category records.
/// Provides hierarchical and navigational structure but contains no
/// user-generated content. Used system-wide for filtering, searching, and
/// permission gating.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique name of the category as displayed to users. Title-cased, 2–60
  /// characters, represents top-level classification (e.g., 'International
  /// Affairs').
  name String

  /// Free-text category description for web UI and moderation guidance.
  /// Explains topic focus, allowed content themes, and usage. Optional but
  /// strongly recommended; up to 255 characters.
  description String?

  /// Integer specifying appearance order in navigation and category lists
  /// (ascending). Configurable by admins for optimal UX.
  display_order Int @db.Integer

  /// Timestamp of initial category creation via admin workflow.
  created_at DateTime @db.Timestamptz

  /// Timestamp of most recent update to any field (name, description,
  /// display_order).
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  pol_eco_board_boards pol_eco_board_boards[]
  pol_eco_board_board_histories_of_previous_category_id pol_eco_board_board_histories[] @relation("pol_eco_board_board_histories_of_previous_category_id")
  pol_eco_board_board_histories_of_new_category_id pol_eco_board_board_histories[] @relation("pol_eco_board_board_histories_of_new_category_id")
  pol_eco_board_posts pol_eco_board_posts[]

  @@unique([name])
  @@index([display_order])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Defines a top-level forum board/section on the platform, each belonging
/// to exactly one category ({@link pol_eco_board_categories}). A board is a
/// logical container for posts, with unique name and code. Board
/// configuration includes description, display order, visibility, and
/// archival state. This model does not directly reference user participation
/// or moderation assignments (handled in separate tables). Used for display
/// navigation, permission gate, and board-level operations. Does not store
/// content; used for board definitions only.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_boards {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Assigned category's {@link pol_eco_board_categories.id}. Each board is
  /// assigned to exactly one active category for taxonomic organization and
  /// navigation.
  pol_eco_board_category_id String @db.Uuid

  /// Unique, human-readable board title. Displayed prominently in navigation.
  /// 2–60 characters, may overlap category names for consistency but globally
  /// unique per board.
  name String

  /// Unique, machine-friendly identifier for the board; used in URLs, admin
  /// operations, and as an external integration key. 2–30 lowercase letters,
  /// numbers, and underscores.
  code String

  /// Optional board description for user guidance and moderation policy. Up to
  /// 255 characters.
  description String?

  /// Whether the board is visible to non-authenticated (guest) users. Used for
  /// UI filtering and role-based access control.
  is_public Boolean

  /// True if the board is archived (closed for new posts/comments but viewable
  /// by privileged roles/admins). Used for compliance and operational
  /// reporting.
  is_archived Boolean

  /// Integer that determines board order in the navigation lists. Lower values
  /// display earlier (ascending sort). Admin-configurable for UX.
  display_order Int @db.Integer

  /// Timestamp of board creation.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update to board settings, description, or archival
  /// state.
  updated_at DateTime @db.Timestamptz

  /// Timestamp if board is logically deleted (soft delete). Null unless
  /// deleted. Used for audit trails, never physically removed from database.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  category pol_eco_board_categories @relation(fields: [pol_eco_board_category_id], references: [id], onDelete: Cascade)

  pol_eco_board_board_statuses pol_eco_board_board_statuses[]
  pol_eco_board_board_histories pol_eco_board_board_histories[]
  pol_eco_board_moderator_board_assignments pol_eco_board_moderator_board_assignments[]

  @@unique([code])
  @@unique([name])
  @@index([pol_eco_board_category_id])
  @@index([display_order])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Singleton table for global service configuration and feature toggles.
/// Contains a single record (enforced in application logic) specifying
/// current values for platform-level settings, system flags, and
/// business-critical constants (e.g., max post length, registration enabled,
/// enforcement deadlines, notification toggles, retention periods). Updated
/// rarely by admins. No user-generated content. Read at app startup. All
/// service domains reference this table for system-wide parameters but do
/// not own or update these fields independently. Record is never deleted or
/// replaced, only updated.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_service_settings {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Enables or disables new user registration across the platform. If false,
  /// registration endpoints and workflows are disabled for all users. Managed
  /// by admins during maintenance, emergencies, or policy changes.
  registration_enabled Boolean

  /// Maximum number of characters allowed in a post's body as enforced by
  /// business and moderation policy.
  max_post_length Int @db.Integer

  /// Maximum number of characters permitted in a comment's body. Used for
  /// input validation and error messaging.
  max_comment_length Int @db.Integer

  /// Default value for new board's is_public field when created by admins.
  /// Guides admin workflow UX.
  default_board_visibility Boolean

  /// System-wide setting (in days) for minimum data retention period for
  /// posts, comments, and audit logs before they're eligible for purge per
  /// policy. Audited by compliance systems.
  data_retention_days Int @db.Integer

  /// Timestamp when service settings record was first created. Set once.
  created_at DateTime @db.Timestamptz

  /// Timestamp of any change to configuration or business flags. Updated
  /// automatically on every change.
  updated_at DateTime @db.Timestamptz
}

schemas.schema-02-actors.prisma:
/// Guest users who access the application without registration; provides a
/// tracked, anonymous footprint for session observation, abuse/IP recording,
/// and guest-to-member analytics. Powers project-level metrics for
/// non-authenticated participation including consent status.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_guests {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// IP address of the guest for session tracking and abuse prevention.
  ip_address String

  /// Device fingerprint or anonymized browser identifier to distinguish unique
  /// guest sessions.
  device_fingerprint String?

  /// Current consent or privacy agreement status text/code for this guest
  /// interaction.
  consent_status String

  /// Timestamp when the guest session was created.
  created_at DateTime @db.Timestamptz

  /// When the guest session record was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([ip_address, device_fingerprint])
  @@index([created_at])
}

/// Registered member accounts, each a unique, verified user. Handles
/// profile, security, lifecycle, audit, and privacy settings for all core
/// platform business. Required for any posting, voting, or reporting.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_members {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique verified email address. Used for login and notifications.
  email String

  /// Hashed password (never plaintext); always required for authentication.
  password_hash String

  /// Public display name; unique within platform locale.
  display_name String

  /// Profile picture URI or file reference; optional at registration.
  profile_image_uri String? @db.VarChar(80000)

  /// Active privacy/consent agreement version for this member.
  consent_status String

  /// Is member active (not banned/deactivated/deleted)?
  is_active Boolean

  /// Last successful login time.
  last_login_at DateTime? @db.Timestamptz

  /// Creation timestamp for the member.
  created_at DateTime @db.Timestamptz

  /// Last update to member account.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp if the member is deleted or banned.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  pol_eco_board_moderators pol_eco_board_moderators?
  pol_eco_board_admins pol_eco_board_admins?
  pol_eco_board_auth_sessions pol_eco_board_auth_sessions[]
  pol_eco_board_role_transitions pol_eco_board_role_transitions[]
  pol_eco_board_account_audits_of_actor_id pol_eco_board_account_audits[] @relation("pol_eco_board_account_audits_of_actor_id")
  pol_eco_board_account_audits_of_target_account_id pol_eco_board_account_audits[] @relation("pol_eco_board_account_audits_of_target_account_id")
  pol_eco_board_posts pol_eco_board_posts[]
  pol_eco_board_post_edits pol_eco_board_post_edits[]
  pol_eco_board_comments pol_eco_board_comments[]
  pol_eco_board_comment_edits pol_eco_board_comment_edits[]
  pol_eco_board_votes pol_eco_board_votes[]
  pol_eco_board_reports pol_eco_board_reports[]
  pol_eco_board_attachments pol_eco_board_attachments[]
  pol_eco_board_sanctions pol_eco_board_sanctions[]
  pol_eco_board_appeals pol_eco_board_appeals[]
  pol_eco_board_notifications pol_eco_board_notifications[]
  pol_eco_board_notification_preferences pol_eco_board_notification_preferences[]

  @@unique([email])
  @@unique([display_name])
  @@index([created_at])
  @@index([is_active])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Moderator accounts elevated from members for content/business enforcement
/// powers. Tracks appointment and privileges, with references to both the
/// member and the appointing admin.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_moderators {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to pol_eco_board_members.id this moderator extends.
  member_id String @db.Uuid

  /// Admin who granted moderator privileges; references
  /// pol_eco_board_admins.id.
  appointed_by_admin_id String @db.Uuid

  /// Date/time when moderator role was granted.
  appointed_at DateTime @db.Timestamptz

  /// If privileges stripped; otherwise null when active.
  revoked_at DateTime? @db.Timestamptz

  /// If this moderator's privileges are currently active.
  is_active Boolean

  /// Timestamp the moderator record was created.
  created_at DateTime @db.Timestamptz

  /// Last moderator record update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  member pol_eco_board_members @relation(fields: [member_id], references: [id], onDelete: Cascade)

  pol_eco_board_board_statuses pol_eco_board_board_statuses[]
  pol_eco_board_board_histories pol_eco_board_board_histories[]
  pol_eco_board_moderator_board_assignments pol_eco_board_moderator_board_assignments[]
  pol_eco_board_moderation_actions pol_eco_board_moderation_actions[]
  pol_eco_board_escalations pol_eco_board_escalations[]

  @@unique([member_id])
  @@index([is_active])
}

/// Platform/system admins with authority for all
/// security/policy/analytics/role management. Each record links an admin to
/// the promoting admin and to their member account for full accountability.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to member this admin extends (pol_eco_board_members.id).
  member_id String @db.Uuid

  /// Numeric admin privilege level (0=standard admin, up to 10 for full super
  /// admins).
  privilege_level Int @db.Integer

  /// Admin who approved this account (self-referential for first/creator).
  appointed_by_admin_id String @db.Uuid

  /// When admin privileges were first granted.
  appointed_at DateTime @db.Timestamptz

  /// If privileges are revoked or demoted, when it happened.
  revoked_at DateTime? @db.Timestamptz

  /// Is this admin active and able to exercise admin powers?
  is_active Boolean

  /// Admin record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last admin record update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  member pol_eco_board_members @relation(fields: [member_id], references: [id], onDelete: Cascade)

  pol_eco_board_role_transitions pol_eco_board_role_transitions[]
  pol_eco_board_board_statuses pol_eco_board_board_statuses[]
  pol_eco_board_board_histories pol_eco_board_board_histories[]
  pol_eco_board_moderation_audits pol_eco_board_moderation_audits[]
  pol_eco_board_escalations pol_eco_board_escalations[]
  pol_eco_board_appeals pol_eco_board_appeals[]

  @@unique([member_id])
  @@index([privilege_level, is_active])
}

/// Tracks all authentication sessions for members (JWT, refresh tokens,
/// SSO). Stores token hash, issued/expiry/revoke, IP/device metadata, audit
/// info. Used for login management, security, and compliance.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_auth_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Foreign key to pol_eco_board_members.id representing the account for this
  /// session.
  member_id String @db.Uuid

  /// Hash of last issued JWT access token (never raw/plaintext).
  access_token String

  /// Hash of active refresh token (never plaintext).
  refresh_token String

  /// IP address from which session was created.
  ip_address String

  /// Device/browser fingerprint, for tracking unique sessions.
  device_fingerprint String?

  /// Authentication provider used: 'native', 'google', 'sso-...', etc.
  provider String

  /// User agent string for device/browser diagnostics.
  user_agent String?

  /// When this session/JWT was issued.
  issued_at DateTime @db.Timestamptz

  /// Session expiry timestamp.
  expires_at DateTime @db.Timestamptz

  /// If revoked, when session/token was terminated; null if active.
  revoked_at DateTime? @db.Timestamptz

  /// Session record created at.
  created_at DateTime @db.Timestamptz

  /// When session record was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  member pol_eco_board_members @relation(fields: [member_id], references: [id], onDelete: Cascade)

  @@unique([access_token])
  @@unique([refresh_token])
  @@index([member_id, issued_at])
  @@index([expires_at])
}

/// Records all role (member/moderator/admin) transitions: promotions,
/// demotions, requests, approvals. Tracks the account affected, approving
/// admin, status, and all audit trail fields.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_role_transitions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The affected account ID (member, moderator, or admin). {@link
  /// pol_eco_board_members.id} or derived types.
  account_id String @db.Uuid

  /// Admin who approved this transition. {@link pol_eco_board_admins.id}
  approved_by_admin_id String @db.Uuid

  /// Original role for the affected account: guest, member, moderator, admin.
  origin_role String

  /// Role after the transition: member, moderator, admin, revoked.
  destination_role String

  /// Explanation or business justification for transition (may be
  /// user-requested, policy, or system action).
  reason String?

  /// Transition status: pending, completed, rejected, or cancelled.
  status String

  /// When the transition was initiated.
  requested_at DateTime @db.Timestamptz

  /// Time transition was approved (null if not finalized).
  approved_at DateTime? @db.Timestamptz

  /// Transition record creation.
  created_at DateTime @db.Timestamptz

  /// Last update for this transition record.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  account pol_eco_board_members @relation(fields: [account_id], references: [id], onDelete: Cascade)
  approvedByAdmin pol_eco_board_admins @relation(fields: [approved_by_admin_id], references: [id], onDelete: Cascade)

  @@index([approved_by_admin_id])

  @@index([account_id, requested_at])
  @@index([status])
}

/// Comprehensive audit trail recording all actions on members, moderators,
/// admins. Logs who did it, who was affected, type/status of business
/// action, and business/technical metadata for compliance/audit. Enables
/// investigation, incident response, and retention.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_account_audits {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// ID of the account performing the action. {@link pol_eco_board_members.id}
  /// or derived.
  actor_id String @db.Uuid

  /// ID of the account affected. {@link pol_eco_board_members.id} or derived.
  target_account_id String @db.Uuid

  /// Business event: create, update, password_change, ban,
  /// privilege_escalation, role_transition, session_invalidate, etc.
  action_type String

  /// JSON-encoded metadata or reference for audit: external system reference,
  /// business justification, etc.
  action_metadata String?

  /// Where event was triggered: API, admin UI, scheduled_job,
  /// external_integration, etc.
  event_source String

  /// Outcome: success, failure, pending, error (for audit chains).
  status String

  /// When this event took place.
  occurred_at DateTime @db.Timestamptz

  /// When audit record was written.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  actor pol_eco_board_members @relation("pol_eco_board_account_audits_of_actor_id", fields: [actor_id], references: [id], onDelete: Cascade)
  targetAccount pol_eco_board_members @relation("pol_eco_board_account_audits_of_target_account_id", fields: [target_account_id], references: [id], onDelete: Cascade)

  @@index([actor_id, occurred_at])
  @@index([target_account_id])
}

schemas.schema-03-board.prisma:
/// Tracks the dynamic status of each board (such as open, locked, archived,
/// visible, or hidden) for business logic and audit trail purposes. Each
/// record represents a status change event for a single board, with
/// effective time, responsible actor, and rationale for the change. Supports
/// reporting and compliance tracking of board accessibility and moderation
/// actions. Links to the target board, relevant actor (admin or moderator),
/// and includes fields for status type, effective timestamp, and status
/// detail.
///
/// @namespace Board
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_board_statuses {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Board's {@link pol_eco_board_boards.id} to which this status applies.
  pol_eco_board_board_id String @db.Uuid

  /// Moderator's {@link pol_eco_board_moderators.id} responsible for this
  /// status change (if set by a moderator).
  actor_moderator_id String? @db.Uuid

  /// Admin's {@link pol_eco_board_admins.id} responsible for this status
  /// change (if set by an admin).
  actor_admin_id String? @db.Uuid

  /// Type of board status (e.g., open, locked, archived, visible, hidden,
  /// merging, splitting, etc). Used for operational logic and reporting;
  /// business logic dictates permissible values.
  status_type String

  /// Date and time the status became effective.
  effective_at DateTime @db.Timestamptz

  /// Business rationale or free-text explanation for status change (e.g.,
  /// moderation reason, admin action, scheduled maintenance).
  reason String?

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Timestamp of the last update to this record.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when this record was soft-deleted (if applicable).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  board pol_eco_board_boards @relation(fields: [pol_eco_board_board_id], references: [id], onDelete: Cascade)
  actorModerator pol_eco_board_moderators? @relation(fields: [actor_moderator_id], references: [id], onDelete: Cascade)
  actorAdmin pol_eco_board_admins? @relation(fields: [actor_admin_id], references: [id], onDelete: Cascade)

  @@index([actor_moderator_id])
  @@index([actor_admin_id])

  @@unique([pol_eco_board_board_id, status_type, effective_at], map: "pol_eco_board_board_statuses_pol_eco_board_board_id_st_5e10c386")
  @@index([created_at])
  @@index([pol_eco_board_board_id, effective_at], map: "pol_eco_board_board_statuses_pol_eco_board_board_id_ef_4ea65ffc")
  @@index([reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Preserves historical records of board assignments and organizational
/// changes. Each record represents a structural or ownership change, such as
/// moving a board between categories, reassigning responsibility, or other
/// changes impacting board lineage and reporting. Supports full auditability
/// of board organizational structure and facilitates operations reporting.
/// References the relevant board, previous and new category, and the acting
/// admin or moderator.
///
/// @namespace Board
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_board_histories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Board's {@link pol_eco_board_boards.id} related to this history change.
  pol_eco_board_board_id String @db.Uuid

  /// The {@link pol_eco_board_categories.id} the board was previously assigned
  /// to (null if first assignment).
  previous_category_id String? @db.Uuid

  /// The {@link pol_eco_board_categories.id} the board is assigned to after
  /// the change.
  new_category_id String @db.Uuid

  /// The {@link pol_eco_board_admins.id} admin who performed the change (if by
  /// admin).
  actor_admin_id String? @db.Uuid

  /// The {@link pol_eco_board_moderators.id} moderator who performed the
  /// change (if by moderator).
  actor_moderator_id String? @db.Uuid

  /// Type of change (e.g., reassignment, merge, split, archive, ownership
  /// transfer). Business logic constrains allowed values, tracked for audit
  /// and reporting.
  change_type String

  /// Business rationale or description for the change (optional), supporting
  /// audit trails and operational reporting.
  change_reason String?

  /// Timestamp when the change occurred.
  changed_at DateTime @db.Timestamptz

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Timestamp of the last update to this record.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when this record was soft-deleted (if applicable).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  board pol_eco_board_boards @relation(fields: [pol_eco_board_board_id], references: [id], onDelete: Cascade)
  previousCategory pol_eco_board_categories? @relation("pol_eco_board_board_histories_of_previous_category_id", fields: [previous_category_id], references: [id], onDelete: Cascade)
  newCategory pol_eco_board_categories @relation("pol_eco_board_board_histories_of_new_category_id", fields: [new_category_id], references: [id], onDelete: Cascade)
  actorAdmin pol_eco_board_admins? @relation(fields: [actor_admin_id], references: [id], onDelete: Cascade)
  actorModerator pol_eco_board_moderators? @relation(fields: [actor_moderator_id], references: [id], onDelete: Cascade)

  @@index([previous_category_id])
  @@index([actor_admin_id])
  @@index([actor_moderator_id])

  @@unique([pol_eco_board_board_id, changed_at], map: "pol_eco_board_board_histories_pol_eco_board_board_id_c_6369dd33")
  @@index([new_category_id])
  @@index([changed_at])
  @@index([change_reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Junction table linking moderators to boards, representing operational
/// moderation assignments. Supports many-to-many mapping of which moderators
/// are actively assigned to which boards. Tracks assignment start, end (if
/// expired/removed), role transfer log, and assignment rationale. Enables
/// runtime dashboards, compliance, and audit trails of moderator coverage
/// for every board or sub-board. References boards and moderators from
/// existing tables.
///
/// @namespace Board
