  post pol_eco_board_posts @relation(fields: [post_id], references: [id], onDelete: Cascade)
  tag pol_eco_board_tags @relation(fields: [tag_id], references: [id], onDelete: Cascade)

  @@unique([post_id, tag_id])
  @@index([tag_id])
  @@index([assigned_at])
}

/// User/member reports on posts or comments for abuse/inappropriateness.
/// Includes reason, type, and optional description supplied by the reporter.
/// Status of moderation report is managed in other domains (moderation can
/// reference this ID for action). Each report links to exactly one post or
/// comment (not both), and to the reporting member. Used for workflow
/// triggering, abuse management, and analytics. Immutable for audit
/// purposes.
///
/// @namespace Participation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Member's {@link pol_eco_board_members.id} who submitted the report.
  /// Audited for abuse prevention.
  reporter_member_id String @db.Uuid

  /// If reporting a post, reference {@link pol_eco_board_posts.id}. Null if
  /// report targets a comment.
  post_id String? @db.Uuid

  /// If reporting a comment, reference {@link pol_eco_board_comments.id}. Null
  /// if report targets a post.
  comment_id String? @db.Uuid

  /// Report type (e.g., spam, hate, off-topic, abuse, other). Must match
  /// business-validated admin codes.
  reason_code String

  /// User-supplied optional description/details. Max length enforced at
  /// business layer (e.g., 250-400 chars).
  reason_description String?

  /// When report was submitted. Used for review queue and escalation SLAs.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  reporter pol_eco_board_members @relation(fields: [reporter_member_id], references: [id], onDelete: Cascade)
  post pol_eco_board_posts? @relation(fields: [post_id], references: [id], onDelete: Cascade)
  comment pol_eco_board_comments? @relation(fields: [comment_id], references: [id], onDelete: Cascade)

  pol_eco_board_moderation_actions pol_eco_board_moderation_actions[]

  @@index([post_id])
  @@index([comment_id])

  @@unique([reporter_member_id, post_id])
  @@unique([reporter_member_id, comment_id])
  @@index([created_at])
}

/// File attachments to posts. Each row represents a file uploaded and
/// attached to a specific post by a member (author). Attachments follow
/// business rules after post creation. File reference (uri) must be unique,
/// and only permitted types/size enforced at application layer. Null
/// deleted_at = active; soft delete for retention. Cascading deletion
/// follows business and legal hold rules.
