  //----
  post pol_eco_board_posts @relation(fields: [post_id], references: [id], onDelete: Cascade)
  author pol_eco_board_members @relation(fields: [author_member_id], references: [id], onDelete: Cascade)

  @@unique([uri])
  @@index([post_id])
  @@index([author_member_id])
  @@index([created_at])
  @@index([file_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-05-moderation.prisma:
/// Represents a single moderation action (decision, removal, warning, etc.)
/// taken on reported content. Each record captures the moderation activity,
/// its executor (moderator/admin), linked report/reference object, operating
/// context (post, comment, or user), action type, rationale, and
/// status/result. This model creates a traceable primary record for every
/// business or privilege-sensitive action, and serves as the authoritative
/// source of action events for compliance or audit purposes. Links to
/// pol_eco_board_reports for the underlying content or event. Also
/// references staff identity via moderator or admin ids from existing user
/// tables.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_moderation_actions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Moderated report's {@link pol_eco_board_reports.id}.
  report_id String @db.Uuid

  /// Moderator or admin's {@link pol_eco_board_moderators.id} or {@link
  /// pol_eco_board_admins.id}. (References either role according to context;
  /// use discriminator field in application logic).
  operator_id String @db.Uuid

  /// Type of moderation action (e.g., edit, remove, warn, suspend, escalate).
  action_type String

  /// Object of moderation (e.g., post, comment, user, attachment).
  target_type String

  /// Current status of this action (pending, completed, overruled, etc.).
  status String

  /// Business reason, operator justification or notes. Required for
  /// auditability. Max 1000 chars.
  rationale String

  /// Result/outcome of action (accepted, rejected, escalated, appealed, etc.)
  outcome String

  /// Timestamp when the moderation action was created.
  created_at DateTime @db.Timestamptz

  /// Last update time for this moderation action record.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp if this action was removed.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  report pol_eco_board_reports @relation(fields: [report_id], references: [id], onDelete: Cascade)
  operator pol_eco_board_moderators @relation(fields: [operator_id], references: [id], onDelete: Cascade)

  pol_eco_board_moderation_audits pol_eco_board_moderation_audits[]
  pol_eco_board_sanctions pol_eco_board_sanctions[]
  pol_eco_board_escalations pol_eco_board_escalations[]
  pol_eco_board_appeals pol_eco_board_appeals[]

  @@unique([report_id, operator_id, action_type], map: "pol_eco_board_moderation_actions_report_id_operator_id_bf4d3c0b")
  @@index([created_at])
  @@index([operator_id])
  @@index([rationale(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Captures comprehensive audit logs for all moderation actions, including
/// pre- and post-action state snapshots, actor identity, and audit metadata.
/// Enables historical tracing and compliance review of all sensitive
/// moderation processes. Every change to a moderation action (remove, edit,
/// escalate) is logged here for transparency and dispute resolution. Links
/// to both action and operator. Provides full visibility into the decision
/// lifecycle.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_moderation_audits {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Related moderation action's {@link pol_eco_board_moderation_actions.id}.
  moderation_action_id String @db.Uuid

  /// Auditor (usually admin or lead moderator) identity, references {@link
  /// pol_eco_board_admins.id} or {@link pol_eco_board_moderators.id}. Use
  /// business logic to distinguish role.
  auditor_id String @db.Uuid

  /// Serialized JSON/text snapshot of moderation action before change. Max
  /// size 2000 chars.
  pre_state_snapshot String

  /// Serialized JSON/text snapshot after action. Max size 2000 chars.
  post_state_snapshot String

  /// Reason for the audit/change. Max 1000 chars.
  reason String

  /// Audit record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Last update time for this audit record.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  moderationAction pol_eco_board_moderation_actions @relation(fields: [moderation_action_id], references: [id], onDelete: Cascade)
  auditor pol_eco_board_admins @relation(fields: [auditor_id], references: [id], onDelete: Cascade)

  @@index([auditor_id])

  @@unique([moderation_action_id, auditor_id, created_at], map: "pol_eco_board_moderation_audits_moderation_action_id_a_466ca590")
  @@index([created_at])
}

/// Formal record of sanctions (temporary or permanent) issued as a result of
/// moderation. Includes details about type, target (user/member/moderator),
/// status, rationale, and duration. Links directly to the action and
/// sanctioned entity for full audit trail. Used for account suspensions,
/// bans, and other participation restrictions. All sanctions must be
/// traceable to the initiating moderation action, with full compliance
/// support.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_sanctions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Underlying moderation action that produced the sanction. {@link
  /// pol_eco_board_moderation_actions.id}.
  moderation_action_id String @db.Uuid

  /// User/member account subject to sanctioning. References {@link
  /// pol_eco_board_members.id}.
  sanctioned_user_id String @db.Uuid

  /// Type of sanction (suspension, ban, warning, probation, cooldown).
  sanction_type String

  /// Sanction status (active, expired, revoked, appealed, overruled).
  status String

  /// Business reason or policy link for the sanction. Max 1000 chars.
  rationale String

  /// When the sanction takes effect.
  start_at DateTime @db.Timestamptz

  /// Scheduled end of sanction (null for permanent/indefinite).
  end_at DateTime? @db.Timestamptz

  /// Record creation date/time.
  created_at DateTime @db.Timestamptz

  /// Record last update date/time.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp, if sanction is removed or redacted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  moderationAction pol_eco_board_moderation_actions @relation(fields: [moderation_action_id], references: [id], onDelete: Cascade)
  sanctionedUser pol_eco_board_members @relation(fields: [sanctioned_user_id], references: [id], onDelete: Cascade)

  @@unique([moderation_action_id, sanctioned_user_id], map: "pol_eco_board_sanctions_moderation_action_id_sanctione_d10b9fcc")
  @@index([start_at])
  @@index([sanctioned_user_id])
