/// Tracks all authentication sessions for members (JWT, refresh tokens,
/// SSO). Stores token hash, issued/expiry/revoke, IP/device metadata, audit
/// info. Used for login management, security, and compliance.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_auth_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Foreign key to pol_eco_board_members.id representing the account for this
  /// session.
  member_id String @db.Uuid

  /// Hash of last issued JWT access token (never raw/plaintext).
  access_token String

  /// Hash of active refresh token (never plaintext).
  refresh_token String

  /// IP address from which session was created.
  ip_address String

  /// Device/browser fingerprint, for tracking unique sessions.
  device_fingerprint String?

  /// Authentication provider used: 'native', 'google', 'sso-...', etc.
  provider String

  /// User agent string for device/browser diagnostics.
  user_agent String?

  /// When this session/JWT was issued.
  issued_at DateTime @db.Timestamptz

  /// Session expiry timestamp.
  expires_at DateTime @db.Timestamptz

  /// If revoked, when session/token was terminated; null if active.
  revoked_at DateTime? @db.Timestamptz

  /// Session record created at.
  created_at DateTime @db.Timestamptz

  /// When session record was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  member pol_eco_board_members @relation(fields: [member_id], references: [id], onDelete: Cascade)

  @@unique([access_token])
  @@unique([refresh_token])
  @@index([member_id, issued_at])
  @@index([expires_at])
