/// Records all role (member/moderator/admin) transitions: promotions,
/// demotions, requests, approvals. Tracks the account affected, approving
/// admin, status, and all audit trail fields.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_role_transitions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The affected account ID (member, moderator, or admin). {@link
  /// pol_eco_board_members.id} or derived types.
  account_id String @db.Uuid

  /// Admin who approved this transition. {@link pol_eco_board_admins.id}
  approved_by_admin_id String @db.Uuid

  /// Original role for the affected account: guest, member, moderator, admin.
  origin_role String

  /// Role after the transition: member, moderator, admin, revoked.
  destination_role String

  /// Explanation or business justification for transition (may be
  /// user-requested, policy, or system action).
  reason String?

  /// Transition status: pending, completed, rejected, or cancelled.
  status String

  /// When the transition was initiated.
  requested_at DateTime @db.Timestamptz

  /// Time transition was approved (null if not finalized).
  approved_at DateTime? @db.Timestamptz

  /// Transition record creation.
  created_at DateTime @db.Timestamptz

  /// Last update for this transition record.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  account pol_eco_board_members @relation(fields: [account_id], references: [id], onDelete: Cascade)
  approvedByAdmin pol_eco_board_admins @relation(fields: [approved_by_admin_id], references: [id], onDelete: Cascade)

  @@index([approved_by_admin_id])

  @@index([account_id, requested_at])
  @@index([status])
}

/// Comprehensive audit trail recording all actions on members, moderators,
/// admins. Logs who did it, who was affected, type/status of business
/// action, and business/technical metadata for compliance/audit. Enables
/// investigation, incident response, and retention.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model pol_eco_board_account_audits {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// ID of the account performing the action. {@link pol_eco_board_members.id}
  /// or derived.
  actor_id String @db.Uuid

  /// ID of the account affected. {@link pol_eco_board_members.id} or derived.
  target_account_id String @db.Uuid

  /// Business event: create, update, password_change, ban,
  /// privilege_escalation, role_transition, session_invalidate, etc.
  action_type String

  /// JSON-encoded metadata or reference for audit: external system reference,
  /// business justification, etc.
  action_metadata String?

