  //----
  // RELATIONS
  //----
  @@unique([action_type, performed_by_id, recorded_at], map: "pol_eco_board_audit_trails_action_type_performed_by_id_66522b0e")
  @@index([recorded_at])
  @@index([audit_context(ops: raw("gin_trgm_ops"))], type: Gin)
