model pol_eco_board_service_metrics {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Short string code identifying metric type (e.g., POST_COUNT,
  /// COMMENT_COUNT, VOTE_VOLUME, API_LATENCY, INCIDENT_COUNT, PURGE_VOLUME).
  metric_code String

  /// Start of the aggregation time window (e.g., hour, day, week).
  metric_window_start DateTime @db.Timestamptz

  /// End of the aggregation window (exclusive).
  metric_window_end DateTime @db.Timestamptz

  /// Integer-valued metric (e.g., count of events, users, incidents in the
